ap-1 justify-content-end"><a class="btn btn-sm btn-outline-primary" href="<?php echo e(route('admin.flights.edit', $flight)); ?>">Edit</a><form method="POST" action="<?php echo e(route('admin.flights.destroy', $flight)); ?>" onsubmit="return confirm('Remove this flight route? Bookings will be unaffected.')"><?php echo csrf_field(); ?>
